source('scripts/load.R')
library(ggplot2)
base<-'case_study/results/';outdir<-'case_study/figures/'
q<-read.csv(paste0(base,'assembly_qc_typing.csv'),check.names=FALSE)
q$QC_pass<-as.logical(toupper(q$QC_pass))
d<-read.csv(paste0(base,'core_pairwise_distances.csv'))
v<-read.csv(paste0(base,'publication_validation.csv'))
s<-jsonlite::read_json(paste0(base,'case_summary.json'),simplifyVector=TRUE)
genes<-read.csv(paste0(base,'amrfinder_all_hits.csv'),check.names=FALSE)
genes<-genes[genes$Type=='AMR',]
cfg<-jsonlite::read_json('case_study/config/study.json',simplifyVector=TRUE)
stopifnot(setequal(q$sample,cfg$samples),!anyDuplicated(q$sample),nrow(d)==choose(sum(q$QC_pass),2))
summary<-list(data_type='public measured bacterial genome assemblies',n=nrow(q),QC_pass=sum(q$QC_pass),ST258=sum(q$sequence_type=='258'),KPC_positive=sum(nzchar(q$KPC_genes)),median_contigs=median(q$contigs),N50_kb_median=median(q$N50)/1000,N50_kb_range=range(q$N50)/1000,median_callable_percent=100*median(q$callable_fraction_before_shared_mask),callable_percent_range=100*range(q$callable_fraction_before_shared_mask),common_core_bases=s$common_callable_bases,common_core_percent=100*s$common_callable_fraction,variable_sites=s$variable_sites,pairwise_snp_median=median(d$snps),pairwise_snp_IQR=unname(quantile(d$snps,c(.25,.75))),pairwise_snp_range=range(d$snps),KPC_alleles=sort(unique(unlist(strsplit(q$KPC_genes,';',fixed=TRUE)))),AMR_gene_union=length(unique(genes[['normalised_gene_symbol']])),AMR_gene_shared=sum(vapply(unique(genes[['normalised_gene_symbol']]),function(g)length(unique(genes[['sample']][genes[['normalised_gene_symbol']]==g]))==nrow(q),logical(1))),scope='Descriptive within-outbreak statistics; pairs and isolates are not independent population observations')
jsonlite::write_json(summary,paste0(base,'descriptive_summary.json'),pretty=TRUE,auto_unbox=TRUE)
save_case<-function(p,name,w=10,h=7){ggsave(paste0(outdir,name,'.png'),p,width=w,height=h,dpi=300,bg='white');ggsave(paste0(outdir,name,'.pdf'),p,width=w,height=h,device='pdf')}
tree<-ape::ladderize(ape::read.tree(paste0(base,'phylogeny/public.treefile')))
stopifnot(setequal(tree$tip.label,q$sample[q$QC_pass]))
nt<-length(tree$tip.label);xx<-ape::node.depth.edgelength(tree);yy<-rep(NA_real_,length(xx));yy[seq_len(nt)]<-seq_len(nt)
ypos<-function(node){if(is.na(yy[node]))yy[node]<<-mean(vapply(tree$edge[tree$edge[,1]==node,2],ypos,numeric(1)));yy[node]};invisible(ypos(nt+1))
ed<-data.frame(x=xx[tree$edge[,1]],xend=xx[tree$edge[,2]],y=yy[tree$edge[,2]],yend=yy[tree$edge[,2]])
vertical<-do.call(rbind,lapply(unique(tree$edge[,1]),function(node){j<-tree$edge[tree$edge[,1]==node,2];data.frame(x=xx[node],y=min(yy[j]),yend=max(yy[j]))}))
tips<-data.frame(x=xx[seq_len(nt)],y=yy[seq_len(nt)],sample=tree$tip.label)
tips$label<-vapply(tips$sample,function(id){z<-q[q$sample==id,];paste0(id,'  |  ST',z$sequence_type,'  |  ',z$KPC_genes)},character(1))
nodes<-data.frame(x=xx[nt+seq_len(tree$Nnode)],y=yy[nt+seq_len(tree$Nnode)],support=tree$node.label,node=nt+seq_len(tree$Nnode));nodes<-nodes[nodes$node!=nt+1&!is.na(nodes$support)&nodes$support!='',]
g<-ggplot()+geom_segment(data=ed,aes(x=x,xend=xend,y=y,yend=yend),colour='grey40')+geom_segment(data=vertical,aes(x=x,xend=x,y=y,yend=yend),colour='grey40')+geom_point(data=tips,aes(x,y),colour='#236c83',size=2.3)+geom_text(data=tips,aes(x=x+max(xx)*.025,y=y,label=label),hjust=0,size=3)+geom_text(data=nodes,aes(x,y,label=support),vjust=-.8,size=2.5,colour='grey25')+scale_x_continuous(expand=expansion(mult=c(.02,.8)),labels=function(x)format(x,scientific=TRUE,digits=2))+scale_y_continuous(breaks=NULL)+labs(title='Public NIH outbreak genomes retain fine genetic structure',subtitle=paste0(nt,' assemblies; GTR+G; full common chromosome with constant sites retained'),x='Expected substitutions per site',y=NULL,caption='Numbers show ultrafast bootstrap support from 1,000 replicates; short branches can remain uncertain.\nArbitrary display root. Genetic proximity does not establish patient-to-patient transmission.')+theme_study()+theme(panel.grid=element_blank())
save_case(g,'public_phylogeny',11,7)
ids<-tree$tip.label;matrix<-matrix(0,length(ids),length(ids),dimnames=list(ids,ids))
for(i in seq_len(nrow(d)))matrix[d$sample_a[i],d$sample_b[i]]<-matrix[d$sample_b[i],d$sample_a[i]]<-d$snps[i]
grid<-expand.grid(sample_a=ids,sample_b=ids);grid$snps<-as.vector(matrix);grid$sample_a<-factor(grid$sample_a,levels=ids);grid$sample_b<-factor(grid$sample_b,levels=rev(ids))
g<-ggplot(grid,aes(sample_a,sample_b,fill=snps))+geom_tile()+geom_text(aes(label=snps),size=2.8,colour='black')+scale_fill_gradient(low='#f7fbff',high='#6baed6')+coord_equal()+labs(title='Pairwise SNP differences on the same callable chromosome',subtitle=paste(format(s$common_callable_bases,big.mark=','),'shared sites after repeat and alignment masks'),x=NULL,y=NULL,fill='SNPs',caption='Every cell uses the same denominator. The selected assemblies are a related outbreak subset.\nCounts are descriptive; clinical transmission cutoffs are not inferred from this matrix.')+theme_study()+theme(axis.text.x=element_text(angle=45,hjust=1),panel.grid=element_blank())
save_case(g,'public_snp_heatmap',9,8)
gn<-sort(unique(genes[['normalised_gene_symbol']]));grid<-expand.grid(sample=ids,gene=gn);grid$present<-mapply(function(id,g)any(genes$sample==id&genes[['normalised_gene_symbol']]==g),as.character(grid$sample),as.character(grid$gene));grid$sample<-factor(grid$sample,levels=rev(ids));grid$gene<-factor(grid$gene,levels=gn)
g<-ggplot(grid,aes(gene,sample,fill=present))+geom_tile(colour='white',linewidth=.3)+scale_fill_manual(values=c('FALSE'='#eef1f3','TRUE'='#236c83'),limits=c('FALSE','TRUE'),breaks=c('FALSE','TRUE'),labels=c('Not detected','Detected'),drop=FALSE)+labs(title='AMRFinderPlus resistance-gene calls in public assemblies',subtitle='Database 2026-08-07.1; translated nucleotide searches',x=NULL,y=NULL,fill=NULL,caption='Gene calls describe sequence evidence; they do not substitute for phenotypic susceptibility testing.\nProtein annotation, expression, resistance mutations and plasmid linkage were not evaluated.')+theme_study()+theme(axis.text.x=element_text(angle=55,hjust=1),panel.grid=element_blank())
save_case(g,'public_amr_heatmap',max(10,length(gn)*.5),7)
z<-rbind(data.frame(sample=q$sample,metric='Callable chromosome (%)',value=100*q$callable_fraction_before_shared_mask),data.frame(sample=q$sample,metric='Assembly N50 (kb)',value=q$N50/1000));z$sample<-factor(z$sample,levels=rev(ids))
g<-ggplot(z,aes(value,sample))+geom_point(colour='#236c83',size=2.5)+facet_wrap(~metric,scales='free_x')+labs(title='Assembly continuity and reference callability describe different properties',subtitle='Public archive assemblies; these are not raw-read QC metrics',x=NULL,y=NULL,caption='Callability is measured before the cohort-wide repeat mask. N50 includes chromosome and accessory contigs.\nSpecies labels come from NCBI metadata; no independent contamination or taxonomic assay is claimed.')+theme_study()
save_case(g,'public_assembly_qc',11,6)
cat('Produced four public-data figures and descriptive R summaries.\n')
